// Private planners. The plan itself is encrypted (PBKDF2 + AES-GCM) and only opens with the right passphrase,
// so the link alone shows nothing. Opened planners are kept in this browser's localStorage like any other planner.
export const PRIVATE = [
  { id: "annika-dec-2026", title: "Annika's planner", salt: "V7rw/zCpz/KRNtCCogDtJQ==", iv: "Msa4LmA7LI4rwCez", data: "" },
];

const bytes = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));

export async function unlock(entry, passphrase) {
  const km = await crypto.subtle.importKey("raw", new TextEncoder().encode(passphrase), "PBKDF2", false, ["deriveKey"]);
  const key = await crypto.subtle.deriveKey({ name: "PBKDF2", salt: bytes(entry.salt), iterations: 200000, hash: "SHA-256" }, km, { name: "AES-GCM", length: 256 }, false, ["decrypt"]);
  const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: bytes(entry.iv) }, key, bytes(entry.data));
  return JSON.parse(new TextDecoder().decode(plain));
}
